import { describeRuntimeCapabilities } from '@cossackframework/framework/runtime-capabilities';

const missing = describeRuntimeCapabilities('cloudflare', {});
if (missing.transports.status !== 'missing-binding' ||
    !missing.transports.missingBindings.includes('COSSACK_SSE') ||
    !missing.transports.missingBindings.includes('COSSACK_OBJECT')) {
  throw new Error('Cloudflare realtime bindings were not reported');
}
const ready = describeRuntimeCapabilities('cloudflare', { COSSACK_SSE: {}, COSSACK_OBJECT: {} });
if (ready.transports.status !== 'available') throw new Error('Expected realtime bindings to satisfy transport requirements');
const node = describeRuntimeCapabilities('node', {});
if (node.processLocalRealtime.status !== 'available' || node.durableState.status !== 'unsupported') {
  throw new Error('Node must remain process-local');
}

import { checkCapabilityRequirements, type CapabilityUse } from '@cossackframework/framework/runtime-capabilities';

const liveFeed: CapabilityUse = {
  feature: 'live-feed',
  source: { file: 'src/pages/live/index.ts' },
  requires: { transports: ['sse'], realtimeCoordination: true },
};
const missing = checkCapabilityRequirements('cloudflare', [liveFeed]);
if (!missing.some(item => item.missingBindings.includes('COSSACK_SSE'))) {
  throw new Error('The plan must identify the missing coordinator binding');
}
if (checkCapabilityRequirements('cloudflare', [liveFeed], ['COSSACK_SSE']).length !== 0) {
  throw new Error('The declared feature should pass once its binding name is present');
}
const processRuntime = checkCapabilityRequirements('node', [{
  ...liveFeed, requires: { durableState: true },
}]);
if (processRuntime[0]?.code !== 'COSSACK_CAPABILITY_UNSUPPORTED') {
  throw new Error('Durable state must be rejected on Node');
}

import { cache, InMemoryCacheStore } from '@cossackframework/framework/cache';

cache.setDefaultStore(new InMemoryCacheStore());
let loads = 0;
const loadCatalog = async () => { loads++; return ['one', 'two']; };
const first = await cache.remember('catalog', 60_000, loadCatalog);
const second = await cache.remember('catalog', 60_000, loadCatalog);
if (first.join(',') !== 'one,two' || second.join(',') !== 'one,two' || loads !== 1) {
  throw new Error('remember should load once while the cached value is present');
}

import { InMemoryCacheStore, KvCacheStore, type CacheKvNamespace } from '@cossackframework/framework/cache';
import { assertStorageRequirements, StorageCapabilityError } from '@cossackframework/framework/storage-capabilities';

const kv: CacheKvNamespace = {
  async get() { return null; },
  async put() {},
  async delete() {},
};
const eventual = new KvCacheStore(kv);
if (eventual.capabilities.consistency !== 'eventual' || eventual.capabilities.locality !== 'shared') {
  throw new Error('KV must be described as shared and eventually consistent');
}
let rejected = false;
try { assertStorageRequirements(eventual.capabilities, { strongConsistency: true }); }
catch (error) { rejected = error instanceof StorageCapabilityError; }
if (!rejected) throw new Error('Eventually consistent KV cannot satisfy a strong consistency requirement');
const local = new InMemoryCacheStore();
if (local.capabilities.locality !== 'process' || local.capabilities.persistence !== 'ephemeral') {
  throw new Error('Memory cache must be scoped to the current process');
}

import { binding, prepareConfigStore, config, env, requireBinding, requireEnv, runWithConfig, ConfigBindingError, requireConfigVariable, configVariable, type ConfigRequirements, type ConfigFactory, type CossackConfigRegistry } from '@cossackframework/framework/config';

declare module '@cossackframework/framework/config' {
  interface CossackConfigRegistry {
    app: { name: string; stage: string };
  }
}

const bindings: Record<string, unknown> = {
  PORT: '81', ENABLED: 'true',
  APP_NAME: 'Cossack example',
  APP_STAGE: 'staging',
  APP_SECRET: 'example-only-secret',
  DB: { marker: 'local-d1' },
};
const appFactory: ConfigFactory = ({ env }) => ({
  name: requireEnv('APP_NAME'),
  stage: env('APP_STAGE', 'local'),
});
const requirements = { variables: {
  PORT: { type: 'number', coerce: true }, ENABLED: { type: 'boolean', coerce: true },
  APP_SECRET: { type: 'string', secret: true }, OPTIONAL: { type: 'string', required: false },
}, bindings: { DB: { kind: 'object' } } } satisfies ConfigRequirements;
const store = prepareConfigStore({ app: appFactory }, bindings, { requirements: { app: requirements }, context: { runtime: 'node' } });

if (config('app.name', 'outside-request') !== 'outside-request') {
  throw new Error('Config outside a request must use its default');
}
await runWithConfig(store, async () => {
  const port: number = requireConfigVariable('PORT', 'number');
  const enabled: boolean = requireConfigVariable('ENABLED', 'boolean');
  if (port !== 81 || !enabled || configVariable('OPTIONAL', 'string') !== undefined) throw new Error('Declared scalar coercion failed');
  const appName: string = config('app.name');
  // @ts-expect-error A misspelled path must not bypass an augmented registry.
  config('app.nmae');
  // @ts-expect-error The fallback must match the registered path's type.
  config('app.name', false);
  const stage: string = config('app.stage');
  const database = binding<{ marker: string }>('DB');
  const requiredDatabase = requireBinding<{ marker: string }>('DB');
  if (appName !== 'Cossack example' || stage !== 'staging' || env('APP_STAGE') !== stage) {
    throw new Error('Request config and string bindings should use the active environment');
  }
  if (database?.marker !== 'local-d1' || requiredDatabase !== database) {
    throw new Error('Raw bindings must preserve the Worker binding object');
  }
  if (requireEnv('APP_SECRET') !== 'example-only-secret') {
    throw new Error('Required string values must be read inside the request');
  }
  let rejectedMissingBinding = false;
  try {
    requireBinding('MISSING_DB');
  } catch (error) {
    rejectedMissingBinding = error instanceof ConfigBindingError && error.code === 'COSSACK_BINDING_MISSING' &&
      error.bindingName === 'MISSING_DB' && !error.message.includes('example-only-secret');
  }
  if (!rejectedMissingBinding) throw new Error('Missing bindings must fail with a safe coded diagnostic');
});

import { DatabaseSync } from 'node:sqlite';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createD1JobStore, jobStateSchema, type JobStateDatabase } from '@cossackframework/framework/jobs';
const directory = await mkdtemp(join(tmpdir(), 'cossack-ledger-guide-'));
let database = new DatabaseSync(join(directory, 'ledger.sqlite'));
function binding(): JobStateDatabase {
  return { prepare(sql) { return { bind(...values) { const statement = database.prepare(sql); return {
    async first<T>() { return (statement.get(...values) ?? null) as T | null; },
    async all<T>() { return { results: statement.all(...values) as T[] }; },
    async run() { return { meta: { changes: Number(statement.run(...values).changes) } }; },
  }; } }; } };
}
const key = 'a'.repeat(64);
const options = { now: 1000, leaseMs: 1000, job: 'receipt', attempt: 99 };
try {
  database.exec(jobStateSchema); // Explicit setup; inspection does not create tables.
  const firstStore = createD1JobStore(binding());
  const first = await firstStore.claim(key, options);
  if (first.status !== 'acquired' || first.attempt !== 1) throw Error('Ledger owns attempts');
  await firstStore.fail(key, first.token, { terminal: false, now: 1001, retryAt: 11000,
    code: 'JOB_TRANSIENT_FAILURE', action: 'inspect-handler-and-provider' });
  database.close(); database = new DatabaseSync(join(directory, 'ledger.sqlite'));
  const restarted = createD1JobStore(binding());
  if ((await restarted.claim(key, { ...options, now: 2000 })).status !== 'busy') throw Error('Restart must retain backoff');
  const second = await restarted.claim(key, { ...options, now: 11000 });
  if (second.status !== 'acquired' || second.attempt !== 2) throw Error('Restart must retain attempts');
  if (await restarted.complete(key, first.token, 11001)) throw Error('Stale claims cannot complete');
  if (!await restarted.complete(key, second.token, 11001)) throw Error('Current claim must complete');
  if ((await restarted.claim(key, { ...options, now: 12000 })).status !== 'completed') throw Error('Terminal keys must deduplicate');
} finally { database.close(); await rm(directory, { recursive: true, force: true }); }
// Actual SQLite proves structural ledger SQL locally; this is not a remote D1 test.

import { DatabaseSync } from 'node:sqlite';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createD1NotificationStore, notificationStateSchema, createCloudflareNotificationEmailProvider, type NotificationStateDatabase } from '@cossackframework/framework/notifications';
import { createNotificationRuntime, defineNotificationTemplate, notificationHtml } from '@cossackframework/core/notifications';
import { input } from '@cossackframework/core/input';
const directory = await mkdtemp(join(tmpdir(), 'cossack-notification-guide-'));
let database = new DatabaseSync(join(directory, 'state.sqlite')); let sends = 0;
function binding(): NotificationStateDatabase {
  return { prepare(sql) { return { bind(...values) { const statement = database.prepare(sql); return {
    async first<T>() { return (statement.get(...values) ?? null) as T | null; },
    async all<T>() { return { results: statement.all(...values) as T[] }; },
    async run() { return { meta: { changes: Number(statement.run(...values).changes) } }; },
  }; } }; } };
}
const provider = createCloudflareNotificationEmailProvider({ async send() { sends++; throw Error('Fixture uncertain send'); } });
function runtime() { return createNotificationRuntime({ namespace: 'guide', store: createD1NotificationStore(binding()),
  preferences: () => true, dispatch: async () => {}, email: { provider, from: 'sender@example.test' },
  templates: { receipt: defineNotificationTemplate({ schema: input.object({ value: input.string({ required: true }) }),
    render(data) { return { subject: 'Receipt', text: data.value, html: notificationHtml`<p>${data.value}</p>` }; },
  }) },
}); }
try {
  database.exec(notificationStateSchema); let service = runtime();
  const queued = await service.enqueue('receipt', { value: 'PRIVATE_BODY' }, { channel: 'email', recipient: { tenantId: 'tenant', userId: 'user', email: 'user@example.test' }, idempotencyKey: 'receipt-1' });
  if ((await service.deliver(queued.id!)).status !== 'unknown') throw Error('Uncertain non-idempotent send must stop');
  database.close(); database = new DatabaseSync(join(directory, 'state.sqlite')); service = runtime();
  if ((await service.deliver(queued.id!)).status !== 'unknown' || Number(sends) !== 1) throw Error('Restart must not blindly resend');
  if (JSON.stringify(await service.inspect(queued.id!)).includes('PRIVATE_')) throw Error('Inspection must redact private content');
} finally { database.close(); await rm(directory, { recursive: true, force: true }); }
// Local SQLite plus an injected binding proves behavior without sending email.
